1	// 离线响应分支可达性诊断（reach）回归测试
2	//
3	// 覆盖（全部为真实场景文件 + `node app.ts reach` 子进程）：
4	// - 三种结论 reachable / covered / contradictory 与配置顺序；
5	// - 共同遮挡：两支匹配枚举 a/b，后一支仅匹配 flag==true，被前两支的“并集”
6	//   共同遮挡（coveredBy 同时列出两支），不是单支包含也不是抽样；
7	// - 枚举剩余值让兜底可达；可选字段缺失与显式 null 分开；样例补全全部必填字段；
8	// - 可空：根可空时 JSON null 落兜底；可空字段上 null 条件可达；不可空字段上
9	//   null 条件矛盾；
10	// - 特殊字段名：空字段名（/）、__proto__、含 / 与 ~ 字段的 ~0/~1 指针；
11	// - 0 与 -0 等价（两支分别钉 0/-0，后一支被前一支遮挡）；
12	// - 类型不符、枚举越界、同一指针互异常量判 contradictory；
13	// - 每个可达分支与可达兜底的样例都原样发送到真实本机 serve，并经请求记录核对
14	//   实际选中的就是所报分支或兜底（正文检查通过、branchSelection 一致）；
15	// - 范围与输入错误退出 2、stderr 定位、stdout 空；全部可达退出 0、有不可达 1，
16	//   兜底不可达不改变退出码。
17	
18	import assert from 'node:assert/strict';
19	import path from 'node:path';
20	import test from 'node:test';
21	import {
22	  makeTempDir,
23	  runCli,
24	  sendRequest,
25	  startServer,
26	  writeConfig,
27	  writeText,
28	  type RawRequest,
29	  type RunningServer,
30	} from './helpers.ts';
31	
32	function resp(body: string, status = 200): unknown {
33	  return { status, headers: {}, body, delay: 0 };
34	}
35	
36	interface ReachReport {
37	  readonly configFile: string;
38	  readonly method: string;
39	  readonly path: string;
40	  readonly branches: ReadonlyArray<{
41	    readonly id: string;
42	    readonly status: 'reachable' | 'covered' | 'contradictory';
43	    readonly example?: RawRequest;
44	    readonly coveredBy?: readonly string[];
45	    readonly reasons?: ReadonlyArray<{ readonly pointer: string; readonly message: string }>;
46	  }>;
47	  readonly fallback: {
48	    readonly status: 'reachable' | 'covered';
49	    readonly example?: RawRequest;
50	    readonly coveredBy?: readonly string[];
51	  };
52	  readonly unreachableBranches: number;
53	}
54	
55	async function runReach(configFile: string, routePath: string): Promise<{ code: number; stdout: string; stderr: string }> {
56	  return runCli(['reach', '--config', configFile, '--path', routePath]);
57	}
58	
59	function postJson(routePath: string, body: string): RawRequest {
60	  return { method: 'POST', path: routePath, headers: { 'Content-Type': 'application/json' }, body };
61	}
62	
63	// 清空记录后发送一条请求，再取请求记录（管理查询本身不记录），
64	// 返回实际响应与该业务请求的记录字段。
65	async function probe(
66	  server: RunningServer,
67	  routePath: string,
68	  body: string,
69	): Promise<{
70	  status: number;
71	  respBody: string;
72	  selection: { kind: string; id?: string } | null;
73	  passed: boolean | null;
74	}> {
75	  await sendRequest(server.port, { method: 'POST', path: '/__contractlab/requests/clear', headers: {}, body: '' });
76	  const res = await sendRequest(server.port, postJson(routePath, body));
77	  const log = JSON.parse(
78	    (await sendRequest(server.port, { method: 'GET', path: '/__contractlab/requests', headers: {}, body: '' })).body,
79	  );
80	  assert.equal(log.records.length, 1, '清空后只有这一条业务请求记录');
81	  const rec = log.records[0];
82	  return {
83	    status: res.status,
84	    respBody: res.body,
85	    selection: rec.branchSelection,
86	    passed: rec.bodyValidationPassed,
87	  };
88	}
89	
90	// 把报告里的一份可达样例发到真实服务：必须 2xx、正文检查通过、
91	// 且实际选中的分支/兜底与报告一致；返回实际响应以便进一步核对响应正文。
92	async function assertExampleSelects(
93	  server: RunningServer,
94	  example: RawRequest,
95	  expected: { kind: 'branch'; id: string } | { kind: 'fallback' },
96	): Promise<{ status: number; respBody: string }> {
97	  assert.deepEqual(example.headers, { 'Content-Type': 'application/json' }, '样例只带必要的 Content-Type 头');
98	  const r = await probe(server, example.path, example.body);
99	  assert.equal(r.passed, true, `样例必须通过正文检查：${example.body}`);
100	  assert.equal(r.status >= 200 && r.status < 300, true, `样例应得到场景成功响应，实际 ${r.status}：${r.respBody}`);
101	  if (expected.kind === 'branch') {
102	    assert.deepEqual(r.selection, { kind: 'branch', id: expected.id }, `样例 ${example.body} 应首先命中分支 ${expected.id}`);
103	  } else {
104	    assert.deepEqual(r.selection, { kind: 'fallback' }, `样例 ${example.body} 应命中兜底`);
105	  }
106	  return { status: r.status, respBody: r.respBody };
107	}
108	
109	// ---------------------------------------------------------------------------
110	// 场景一：共同遮挡（题述原例的精确形态）+ 矛盾分支 + 兜底被全覆盖
111	// ---------------------------------------------------------------------------
112	
113	function jointShadowConfig(): unknown {
114	  return {
115	    endpoints: [
116	      {
117	        method: 'POST',
118	        path: '/orders',
119	        requestBody: {
120	          type: 'object',
121	          fields: {
122	            state: { type: 'string', enum: ['a', 'b'], required: true },
123	            flag: { type: 'boolean' },
124	          },
125	          additionalProperties: false,
126	        },
127	        responses: [resp('FB')],
128	        branches: [
129	          { id: 'is-a', when: { '/state': 'a' }, responses: [resp('BR-A')] },
130	          { id: 'is-b', when: { '/state': 'b' }, responses: [resp('BR-B')] },
131	          { id: 'flag-only', when: { '/flag': true }, responses: [resp('BR-FLAG')] },
132	          { id: 'impossible', when: { '/state': 'c' }, responses: [resp('BR-C')] },
133	        ],
134	      },
135	    ],
136	  };
137	}
138	
139	test('共同遮挡：flag-only 被 is-a/is-b 两支并集共同遮挡；矛盾分支定位；样例真实命中', { timeout: 30_000 }, async (t) => {
140	  const dir = await makeTempDir(t);
141	  const file = await writeConfig(dir, 'scenes.json', jointShadowConfig());
142	  const server = await startServer(file);
143	  t.after(server.close);
144	
145	  const result = await runReach(file, '/orders');
146	  assert.equal(result.code, 1, '存在 covered/contradictory 分支，退出 1');
147	  const report = JSON.parse(result.stdout) as ReachReport;
148	  assert.equal(report.method, 'POST');
149	  assert.equal(report.path, '/orders');
150	  assert.equal(report.configFile, file);
151	  assert.equal(report.unreachableBranches, 2);
152	
153	  const byId = new Map(report.branches.map((b) => [b.id, b]));
154	  assert.deepEqual(report.branches.map((b) => b.id), ['is-a', 'is-b', 'flag-only', 'impossible']);
155	
156	  // is-a / is-b 可达，样例补全必填字段
157	  const a = byId.get('is-a') as ReachReport['branches'][number];
158	  assert.equal(a.status, 'reachable');
159	  assert.equal(a.example?.body, '{"state":"a"}');
160	  const aHit = await assertExampleSelects(server, a.example as RawRequest, { kind: 'branch', id: 'is-a' });
161	  assert.equal(aHit.respBody, 'BR-A');
162	
163	  const b = byId.get('is-b') as ReachReport['branches'][number];
164	  assert.equal(b.status, 'reachable');
165	  const bHit = await assertExampleSelects(server, b.example as RawRequest, { kind: 'branch', id: 'is-b' });
166	  assert.equal(bHit.respBody, 'BR-B');
167	
168	  // flag-only 被前两支“共同”遮挡：coveredBy 必须同时列出两支
169	  const flag = byId.get('flag-only') as ReachReport['branches'][number];
170	  assert.equal(flag.status, 'covered');
171	  assert.deepEqual(flag.coveredBy, ['is-a', 'is-b']);
172	  assert.equal('example' in flag, false, '不可达分支不给样例');
173	
174	  // 真实核对遮挡：满足 flag-only 的两类合格正文分别先命中 is-a / is-b
175	  const hitA = await probe(server, '/orders', '{"state":"a","flag":true}');
176	  assert.deepEqual(hitA.selection, { kind: 'branch', id: 'is-a' });
177	  assert.equal(hitA.respBody, 'BR-A');
178	  const hitB = await probe(server, '/orders', '{"state":"b","flag":true}');
179	  assert.deepEqual(hitB.selection, { kind: 'branch', id: 'is-b' });
180	  assert.equal(hitB.respBody, 'BR-B');
181	
182	  // impossible：条件与枚举矛盾
183	  const impossible = byId.get('impossible') as ReachReport['branches'][number];
184	  assert.equal(impossible.status, 'contradictory');
185	  assert.equal('example' in impossible, false);
186	  assert.ok(impossible.reasons?.some((r) => r.pointer === '/state' && r.message.includes('c')));
187	  // 该条件值在真实服务上直接 400，没有任何分支会被命中
188	  const c = await probe(server, '/orders', '{"state":"c"}');
189	  assert.equal(c.status, 400);
190	  assert.equal(c.passed, false);
191	  assert.equal(c.selection, null);
192	
193	  // 兜底也被两支并集覆盖（仅信息，不改变退出码的计数）
194	  assert.equal(report.fallback.status, 'covered');
195	  assert.deepEqual(report.fallback.coveredBy, ['is-a', 'is-b']);
196	  assert.equal('example' in report.fallback, false);
197	});
198	
199	// ---------------------------------------------------------------------------
200	// 场景二：枚举剩余值 + 可选字段缺失 => 兜底可达；样例真实命中兜底
201	// ---------------------------------------------------------------------------
202	
203	test('枚举剩余值与可选字段缺失：兜底可达，样例省略可选字段并真实落兜底；全部可达退出 0', { timeout: 30_000 }, async (t) => {
204	  const dir = await makeTempDir(t);
205	  const config: unknown = {
206	    endpoints: [
207	      {
208	        method: 'POST',
209	        path: '/orders',
210	        requestBody: {
211	          type: 'object',
212	          fields: {
213	            state: { type: 'string', enum: ['a', 'b', 'c'], required: true },
214	            note: { type: 'string' },
215	            flag: { type: 'boolean' },
216	          },
217	          additionalProperties: false,
218	        },
219	        responses: [resp('FB')],
220	        branches: [
221	          { id: 'is-a', when: { '/state': 'a' }, responses: [resp('BR-A')] },
222	          { id: 'is-b', when: { '/state': 'b' }, responses: [resp('BR-B')] },
223	          { id: 'note-x', when: { '/note': 'x' }, responses: [resp('BR-NOTE')] },
224	        ],
225	      },
226	    ],
227	  };
228	  const file = await writeConfig(dir, 'scenes.json', config);
229	  const server = await startServer(file);
230	  t.after(server.close);
231	
232	  const result = await runReach(file, '/orders');
233	  assert.equal(result.code, 0, result.stderr);
234	  const report = JSON.parse(result.stdout) as ReachReport;
235	  assert.equal(report.unreachableBranches, 0);
236	
237	  const byId = new Map(report.branches.map((b) => [b.id, b]));
238	  for (const id of ['is-a', 'is-b', 'note-x']) {
239	    assert.equal(byId.get(id)?.status, 'reachable', `${id} 应可达`);
240	    await assertExampleSelects(server, byId.get(id)?.example as RawRequest, { kind: 'branch', id });
241	  }
242	  // note-x 的样例必须显式带上 note，同时补全必填的 state（取未被前两支占用的 c）
243	  const noteExample = JSON.parse((byId.get('note-x') as ReachReport['branches'][number]).example?.body as string);
244	  assert.equal(noteExample.note, 'x');
245	
246	  // 兜底可达：枚举剩余值 c + 可选字段全部缺失
247	  assert.equal(report.fallback.status, 'reachable');
248	  const fbBody = report.fallback.example?.body;
249	  assert.equal(fbBody, '{"state":"c"}', '样例只补全必填字段，省略可选的 note/flag');
250	  const fbHit = await assertExampleSelects(server, report.fallback.example as RawRequest, { kind: 'fallback' });
251	  assert.equal(fbHit.respBody, 'FB');
252	
253	  // 显式 null 与缺失不同：state c + note:null（note 不可空）应被真实服务 400
254	  const nullNote = await probe(server, '/orders', '{"state":"c","note":null}');
255	  assert.equal(nullNote.status, 400);
256	  assert.equal(nullNote.selection, null);
257	});
258	
259	// ---------------------------------------------------------------------------
260	// 场景三：可空根（null 落兜底）、可空字段上的 null 条件、不可空字段上矛盾
261	// ---------------------------------------------------------------------------
262	
263	test('可空：根 null 落兜底；可空字段 null 条件可达；不可空字段 null 条件矛盾', { timeout: 30_000 }, async (t) => {
264	  const dir = await makeTempDir(t);
265	  const config: unknown = {
266	    endpoints: [
267	      {
268	        method: 'POST',
269	        path: '/orders',
270	        requestBody: {
271	          type: 'object',
272	          nullable: true,
273	          fields: {
274	            state: { type: 'string', enum: ['a', 'b'], required: true },
275	            flag: { type: 'boolean', nullable: true },
276	            note: { type: 'string' },
277	          },
278	          additionalProperties: false,
279	        },
280	        responses: [resp('FB')],
281	        branches: [
282	          { id: 'flag-null', when: { '/flag': null }, responses: [resp('BR-NULL')] },
283	          { id: 'is-a', when: { '/state': 'a' }, responses: [resp('BR-A')] },
284	          { id: 'is-b', when: { '/state': 'b' }, responses: [resp('BR-B')] },
285	          { id: 'note-null', when: { '/note': null }, responses: [resp('BR-NNOTE')] },
286	        ],
287	      },
288	    ],
289	  };
290	  const file = await writeConfig(dir, 'scenes.json', config);
291	  const server = await startServer(file);
292	  t.after(server.close);
293	
294	  const result = await runReach(file, '/orders');
295	  assert.equal(result.code, 1); // note-null 矛盾
296	  const report = JSON.parse(result.stdout) as ReachReport;
297	  const byId = new Map(report.branches.map((b) => [b.id, b]));
298	
299	  // 可空字段上的 null 条件可达：样例在 flag 处显式为 null（不是缺失）
300	  const flagNull = byId.get('flag-null') as ReachReport['branches'][number];
301	  assert.equal(flagNull.status, 'reachable');
302	  const fnBody = JSON.parse(flagNull.example?.body as string);
303	  assert.equal(fnBody.flag, null);
304	  assert.equal(Object.prototype.hasOwnProperty.call(fnBody, 'flag'), true);
305	  const fnHit = await assertExampleSelects(server, flagNull.example as RawRequest, { kind: 'branch', id: 'flag-null' });
306	  assert.equal(fnHit.respBody, 'BR-NULL');
307	
308	  // 缺失字段不等于 null：state a 但不带 flag 时不命中 flag-null（落后续分支）
309	  const missingFlag = await probe(server, '/orders', '{"state":"a"}');
310	  assert.deepEqual(missingFlag.selection, { kind: 'branch', id: 'is-a' });
311	
312	  // 不可空字段上的 null 条件矛盾
313	  const noteNull = byId.get('note-null') as ReachReport['branches'][number];
314	  assert.equal(noteNull.status, 'contradictory');
315	  assert.ok(noteNull.reasons?.some((r) => r.pointer === '/note'));
316	  const noteNullReq = await probe(server, '/orders', '{"state":"a","note":null}');
317	  assert.equal(noteNullReq.status, 400);
318	
319	  // 根可空：JSON null 不命中任何字段分支，兜底可达且样例正文就是 null
320	  assert.equal(report.fallback.status, 'reachable');
321	  assert.equal(report.fallback.example?.body, 'null');
322	  const rootNull = await assertExampleSelects(server, report.fallback.example as RawRequest, { kind: 'fallback' });
323	  assert.equal(rootNull.respBody, 'FB');
324	});
325	
326	// ---------------------------------------------------------------------------
327	// 场景四：特殊字段名（空名 / __proto__ / ~0 / ~1）
328	// ---------------------------------------------------------------------------
329	
330	test('特殊字段名：空字段名、__proto__、斜杠与波浪号字段的单段指针', { timeout: 30_000 }, async (t) => {
331	  const fields: Record<string, unknown> = Object.create(null);
332	  fields[''] = { type: 'string' };
333	  fields['__proto__'] = { type: 'integer' };
334	  fields['a/b'] = { type: 'boolean' };
335	  fields['a~b'] = { type: 'boolean' };
336	  const dir = await makeTempDir(t);
337	  const config: unknown = {
338	    endpoints: [
339	      {
340	        method: 'POST',
341	        path: '/special',
342	        requestBody: { type: 'object', fields, additionalProperties: false },
343	        responses: [resp('FB')],
344	        branches: [
345	          { id: 'empty', when: { '/': 'x' }, responses: [resp('BR-EMPTY')] },
346	          { id: 'proto', when: { '/__proto__': 0 }, responses: [resp('BR-PROTO')] },
347	          { id: 'slash', when: { '/a~1b': true }, responses: [resp('BR-SLASH')] },
348	          { id: 'tilde', when: { '/a~0b': true }, responses: [resp('BR-TILDE')] },
349	        ],
350	      },
351	    ],
352	  };
353	  const file = await writeConfig(dir, 'scenes.json', config);
354	  const server = await startServer(file);
355	  t.after(server.close);
356	
357	  const result = await runReach(file, '/special');
358	  assert.equal(result.code, 0, result.stderr);
359	  const report = JSON.parse(result.stdout) as ReachReport;
360	  const byId = new Map(report.branches.map((b) => [b.id, b]));
361	
362	  const expectedBodies: Record<string, string> = {
363	    empty: 'BR-EMPTY',
364	    proto: 'BR-PROTO',
365	    slash: 'BR-SLASH',
366	    tilde: 'BR-TILDE',
367	  };
368	  for (const id of ['empty', 'proto', 'slash', 'tilde']) {
369	    const branch = byId.get(id) as ReachReport['branches'][number];
370	    assert.equal(branch.status, 'reachable', `${id} 应可达`);
371	    const hit = await assertExampleSelects(server, branch.example as RawRequest, { kind: 'branch', id });
372	    assert.equal(hit.respBody, expectedBodies[id]);
373	  }
374	
375	  // 空对象不命中任何支：兜底可达
376	  assert.equal(report.fallback.status, 'reachable');
377	  assert.equal(report.fallback.example?.body, '{}');
378	  const fb = await assertExampleSelects(server, report.fallback.example as RawRequest, { kind: 'fallback' });
379	  assert.equal(fb.respBody, 'FB');
380	});
381	
382	// ---------------------------------------------------------------------------
383	// 场景五：0 与 -0 等价导致的遮挡；以及同指针互异/类型不符矛盾
384	// ---------------------------------------------------------------------------
385	
386	test('0 与 -0 等价：后支被前支遮挡；类型不符与同指针互异常量判矛盾', { timeout: 30_000 }, async (t) => {
387	  const dir = await makeTempDir(t);
388	  const config: unknown = {
389	    endpoints: [
390	      {
391	        method: 'POST',
392	        path: '/nums',
393	        requestBody: {
394	          type: 'object',
395	          fields: { n: { type: 'integer', enum: [0, 1] }, flag: { type: 'boolean' } },
396	          additionalProperties: false,
397	        },
398	        responses: [resp('FB')],
399	        branches: [
400	          { id: 'zero', when: { '/n': 0 }, responses: [resp('BR-ZERO')] },
401	          { id: 'neg-zero', when: { '/n': -0 }, responses: [resp('BR-NEG')] },
402	          { id: 'type-bad', when: { '/flag': 'true' }, responses: [resp('BR-TB')] },
403	          { id: 'enum-miss', when: { '/n': 2 }, responses: [resp('BR-EM')] },
404	        ],
405	      },
406	    ],
407	  };
408	  const file = await writeConfig(dir, 'scenes.json', config);
409	  const server = await startServer(file);
410	  t.after(server.close);
411	
412	  const result = await runReach(file, '/nums');
413	  assert.equal(result.code, 1);
414	  const report = JSON.parse(result.stdout) as ReachReport;
415	  const byId = new Map(report.branches.map((b) => [b.id, b]));
416	
417	  const zero = byId.get('zero') as ReachReport['branches'][number];
418	  assert.equal(zero.status, 'reachable');
419	  await assertExampleSelects(server, zero.example as RawRequest, { kind: 'branch', id: 'zero' });
420	
421	  // -0 与 0 数值相等：neg-zero 被 zero 遮挡
422	  const neg = byId.get('neg-zero') as ReachReport['branches'][number];
423	  assert.equal(neg.status, 'covered');
424	  assert.deepEqual(neg.coveredBy, ['zero']);
425	  const negHit = await probe(server, '/nums', '{"n":-0}');
426	  assert.deepEqual(negHit.selection, { kind: 'branch', id: 'zero' });
427	  assert.equal(negHit.respBody, 'BR-ZERO');
428	
429	  // 类型不符
430	  const typeBad = byId.get('type-bad') as ReachReport['branches'][number];
431	  assert.equal(typeBad.status, 'contradictory');
432	  assert.ok(typeBad.reasons?.some((r) => r.pointer === '/flag'));
433	
434	  // 枚举越界（JSON 配置中同一 when 键无法保留重复键，故互异常量以枚举越界见证）
435	  const enumMiss = byId.get('enum-miss') as ReachReport['branches'][number];
436	  assert.equal(enumMiss.status, 'contradictory');
437	  assert.ok(enumMiss.reasons?.some((r) => r.pointer === '/n' && r.message.includes('枚举')));
